create table if not exists classroom_config (id uuid primary key default gen_random_uuid(), max_students int default 50, max_cameras int default 10, reconnect_grace_seconds int default 180, board_max_image_size_mb int default 10, board_max_events_per_minute int default 120, chat_enabled_default boolean default true, recording_enabled_default boolean default false, created_at timestamptz default now(), updated_at timestamptz default now()); alter table classroom_config enable row level security; insert into classroom_config (max_students,max_cameras,reconnect_grace_seconds) select 50,10,180 where not exists (select 1 from classroom_config);
